    if not fg:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c in fg), max(r for r, c in fg)
    c0, c1 = min(c for r, c in fg), max(c for r, c in fg)

    # Preserve a regularly repeated lattice pattern.
    row_patterns = [
        tuple(c for c in range(c0, c1 + 1) if grid[r][c] != bg)
        for r in range(r0, r1 + 1)
    ]
    if (len(row_patterns) >= 3
        and all(p == row_patterns[1] for p in row_patterns[1:-1])
        and len(set(row_patterns[1])) >= 2):
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    def fill_row(r):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] != bg]
        if len(cols) >= 2:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    def fill_col(c):
        rows = [r for r in range(r0, r1 + 1) if grid[r][c] != bg]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    for r in (r0, r1):
        fill_row(r)
    for c in (c0, c1):
